 private function transfer(Bundle$b,ProductionScan$s,string$from,string$to,User$u):void{$transfer=WipTransfer::create(['company_id'=>$b->company_id,'production_order_id'=>$b->production_order_id,'bundle_id'=>$b->id,'source_scan_id'=>$s->id,'from_stage'=>$from,'to_stage'=>$to,'qty'=>$b->qty,'transferred_at'=>$s->scanned_at,'created_by'=>$u->id,'created_at'=>now()]);$this->audit->record('create',$transfer,after:['bundle_no'=>$b->bundle_no,'from_stage'=>$from,'to_stage'=>$to,'qty'=>(float)$b->qty]);}
 public function eligibleBundles(int$c,?int$mo=null):array{$q=Bundle::withoutGlobalScopes()->where('company_id',$c)->where('status','ACTIVE')->where('current_stage','CUTTING')->with(['cutOutput.lay','cutOrderLine']);if($mo)$q->where('production_order_id',$mo);return$q->orderBy('bundle_no')->get()->filter(fn(Bundle$b)=>$b->cut_output_id===null||$b->cutOutput?->lay?->status==='COMPLETED')->map(fn(Bundle$b)=>['bundle_no'=>$b->bundle_no,'qty'=>(float)$b->qty,'production_order_id'=>$b->production_order_id,'cut_output_id'=>$b->cut_output_id,'lineage_complete'=>$b->cut_output_id!==null])->values()->all();}
