 public function lineage(int$c,string$bundleNo):array{$b=Bundle::withoutGlobalScopes()->where('company_id',$c)->where('bundle_no',$bundleNo)->with(['wipTransfers.sourceScan.operation','scans.operation','cutOutput.lay.rolls.fabricRoll'])->first();if(!$b)throw new RuntimeException('Bundle tidak ditemukan pada company ini.');$finishingInputs=$b->scans->where('stage','FINISHING')->where('direction','IN')->values();$finishingOutputs=$b->scans->where('stage','FINISHING')->where('direction','OUT')->values();$qcPass=DB::table('qc_inspections')->where('company_id',$c)->where('production_order_id',$b->production_order_id)->where('stage','FINAL')->where('verdict','PASS')->exists();return['bundle'=>$b,'sewing_inputs'=>$b->scans->where('stage','SEWING')->where('direction','IN')->values(),'sewing_outputs'=>$b->scans->where('stage','SEWING')->where('direction','OUT')->values(),'wip_transfers'=>$b->wipTransfers,'finishing_inputs'=>$finishingInputs,'finishing_outputs'=>$finishingOutputs,'finishing_source'=>$b->wipTransfers->first(fn($t)=>$t->from_stage==='SEWING'&&$t->to_stage==='FINISHING'),'packing_boundary'=>['finishing_output_available'=>$finishingOutputs->isNotEmpty(),'qc_final_pass_required'=>true,'qc_final_pass'=>$qcPass,'direct_bundle_to_carton_defined'=>false,'status'=>'NOT_DEFINED']];}
